def gen(rng):
    def fmt(a, k):
        return f"{len(a)} {k}\n" + ' '.join(map(str, a))
    tests = [fmt([5], 0), fmt([5], 1), fmt([-3], 1), fmt([4, 4, 4, 4], 2), fmt([1, 2, 3], 3),
             fmt([-5, 2, -5, 8], 4), fmt([10**9, -10**9], 1), fmt([7, 3, 9, 1, 4], 2)]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            a = [rng.randint(-10, 10) for _ in range(n)]
            tests.append(fmt(a, rng.randint(0, n)))
    for _ in range(3):
        n = rng.randint(5, 40)
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)], rng.randint(0, n)))
    N = 10**5
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)], N // 2))
    tests.append(fmt([10**9] * N, N - 1))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)], 0))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], N))
    tests.append(fmt([rng.randint(-5, 5) for _ in range(N)], rng.randint(0, N)))
    return tests

